    if (raw2[0].start != 0 || raw2[0].finish != 0 || raw2[0].eos != 0) { std::printf("00afe4b0_TEST FAIL\n"); return 1; }
    std::free(raw[0].start); std::free(raw[1].start); std::free(raw); std::free(raw2);
    std::printf("00afe4b0_TEST PASS\n");
    return 0;
}

